{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has very low oral bioavailability (≤3%) in humans, supporting low F for the sulfated carbohydrate query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Zanamivir, a polar sugar-like molecule with a carboxylate, has absolute oral bioavailability of only 2%, supporting low F for the similarly polar sugar-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate, a small molecule containing a sulfonate group, has absolute oral bioavailability of ~11%, supporting low F for the sulfate-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "N-acetylcysteine, which shares the N-acetyl group and has a carboxylate, shows oral bioavailability of ~4-10% in multiple studies, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a glucosinolate with a sulfate and sugar moiety, has oral bioavailability of ~5%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "One report suggests oral acetylcysteine bioavailability may be around 80%, but this is inconsistent with multiple other studies reporting 4-10% and is not transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is a sulfated disaccharide with a carboxylate and sulfate, making it highly polar and poorly absorbed. All structurally related compounds with similar polar/charged groups (sulfated polysaccharides, zanamivir, acamprosate, N-acetylcysteine, glucoraphanin) have oral bioavailability well below 20%. Therefore, predict low.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule; however, the consistent low bioavailability across diverse but related polar/charged molecules strongly supports the prediction.",
    "The single high report for N-acetylcysteine (C04) is an outlier and not transferable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

